// ⚠️ IMPORTANT : Copier le même secret que dans le workflow chatbot
// (noeud "Code in JavaScript1", variable "expected")
const EXPECTED_SECRET = 'OnpointGrowth34';

const headers = $json?.headers ?? {};
const got =
  headers['x-emma-secret'] ||
  headers['X-Emma-Secret'] ||
  $json?.body?.emmaSecret ||
  '';

if (!EXPECTED_SECRET || EXPECTED_SECRET === '__MEME_SECRET_QUE_CHATBOT__') {
  throw new Error('Secret non configuré — ouvrir le noeud et remplacer le placeholder.');
}

if (got !== EXPECTED_SECRET) {
  throw new Error('Unauthorized: secret manquant ou invalide');
}

const body = $json?.body ?? {};
const sessionId = (body.sessionId || '').trim();
const question = (body.question || '').trim();
const satisfaction = (body.satisfaction || '').trim();

if (!sessionId) throw new Error('Champ sessionId requis');
if (!question) throw new Error('Champ question requis');
if (satisfaction !== 'positif' && satisfaction !== 'negatif') {
  throw new Error('satisfaction doit être "positif" ou "negatif"');
}

const esc = (s) => s.replace(/'/g, "''");

return [{
  json: {
    sessionId: esc(sessionId),
    question: esc(question),
    satisfaction
  }
}];

const result = $input.first()?.json ?? {};

if (result.updated === true || result.updated === 'true') {
  return [{ json: { ok: true, logId: result.log_id, satisfaction: result.satisfaction } }];
}

return [{ json: { ok: false, error: 'Aucun log chatbot correspondant à cette session/question.' } }];
